#include "game/Player.h"
#include "rendering/AssetManager.h"
#include "audio/AudioSystem.h"
#include <algorithm>
#include <cmath>

namespace district_fury {
namespace {
float DepthScale(float laneY) { const float t = std::clamp((laneY-kLaneMinY)/(kLaneMaxY-kLaneMinY),0.0f,1.0f); return 0.86f+0.26f*t; }
}
Player::Player(){Reset();}
void Player::Reset(){position={180,565,0};velocity={0,0,0};facing=Facing::Right;state=PlayerState::Idle;attackType=AttackType::None;maxHp=100;hp=maxHp;maxSp=100;sp=maxSp;maxRage=100;rage=0;isRageMode=false;stateTimer=0;attackElapsed=0;attackDuration=0;dashTimer=0;dashInvulnerability=0;comboWindow=0;spRegenAccumulator=0;rageDrainAccumulator=0;blockDamageReduction=.78f;blockTimer=0;comboCount=0;comboStep=0;hasHit=false;energyReleased=false;animator=Animator{};}
void Player::SetState(PlayerState s){if(state==s&&s!=PlayerState::Attack)return;state=s;hasHit=false;switch(state){case PlayerState::Idle:animator.Play(animator.normalizedAtlas?AnimationClip{0,3,.12f,true}:AnimationClip{0,4,.12f,true});break;case PlayerState::Walk:animator.Play(animator.normalizedAtlas?AnimationClip{4,7,.105f,true}:AnimationClip{0,4,.10f,true});break;case PlayerState::Dash:animator.Play(animator.normalizedAtlas?AnimationClip{14,14,.08f,false}:AnimationClip{0,4,.08f,false});break;case PlayerState::Block:animator.Play(animator.normalizedAtlas?AnimationClip{3,3,.10f,true}:AnimationClip{0,4,.10f,true});blockTimer=0;break;case PlayerState::Hit:animator.Play(animator.normalizedAtlas?AnimationClip{13,13,.08f,false}:AnimationClip{0,4,.08f,false});stateTimer=.17f;break;case PlayerState::Defeat:animator.Play(animator.normalizedAtlas?AnimationClip{15,15,.10f,false}:AnimationClip{14,14,.10f,false});break;case PlayerState::Attack:break;}}
static void EnsurePlayerAnimator(Animator& a){if(a.texture.id!=0)return;Texture2D clean=AssetManager::Get().GetTexture("rayden_clean");if(clean.id!=0){a.Init(clean,4,4,true);a.Play({0,3,.12f,true});return;}Texture2D legacy=AssetManager::Get().GetTexture("rayden_sheet");if(legacy.id!=0){a.Init(legacy,5,3,false);a.Play({0,4,.12f,true});}}
void Player::Update(float dt){EnsurePlayerAnimator(animator);animator.Update(dt);dashInvulnerability=std::max(0.0f,dashInvulnerability-dt);if(comboWindow>0){comboWindow-=dt;if(comboWindow<=0){comboWindow=0;comboCount=0;comboStep=0;}}if(isRageMode){rageDrainAccumulator+=dt;if(rageDrainAccumulator>=.05f){int drain=std::max(1,(int)(rageDrainAccumulator*20));rage=std::max(0,rage-drain);rageDrainAccumulator=0;}if(rage<=0){rage=0;isRageMode=false;}}if(state==PlayerState::Defeat)return;if(state==PlayerState::Hit){stateTimer-=dt;position.x+=velocity.x*dt;position.y+=velocity.y*dt;velocity.x*=.80f;velocity.y*=.80f;if(stateTimer<=0)SetState(PlayerState::Idle);position.x=std::clamp(position.x,kStageStartX,kStageEndX-90.f);position.y=std::clamp(position.y,kLaneMinY,kLaneMaxY);return;}if(state==PlayerState::Dash){dashTimer-=dt;float d=facing==Facing::Right?1.f:-1.f;position.x+=d*700.f*dt;position.x=std::clamp(position.x,kStageStartX,kStageEndX-90.f);if(dashTimer<=0)SetState(PlayerState::Idle);return;}if(state==PlayerState::Attack){attackElapsed+=dt;stateTimer-=dt;if(attackType==AttackType::Energy&&!energyReleased&&attackElapsed>=.20f)energyReleased=true;if(stateTimer<=0||animator.isFinished){attackType=AttackType::None;SetState(PlayerState::Idle);}return;}if(IsKeyDown(KEY_B)){attackType=AttackType::None;if(state!=PlayerState::Block)SetState(PlayerState::Block);blockTimer+=dt;return;}if(state==PlayerState::Block)SetState(PlayerState::Idle);Vector2 move={0,0};if(IsKeyDown(KEY_W))move.y-=1;if(IsKeyDown(KEY_S))move.y+=1;if(IsKeyDown(KEY_A))move.x-=1;if(IsKeyDown(KEY_D))move.x+=1;bool moving=move.x!=0||move.y!=0;float speed=isRageMode?285.f:245.f;if(moving){float len=std::sqrt(move.x*move.x+move.y*move.y);position.x+=(move.x/len)*speed*dt;position.y+=(move.y/len)*speed*.70f*dt;if(move.x<0)facing=Facing::Left;if(move.x>0)facing=Facing::Right;if(state!=PlayerState::Walk)SetState(PlayerState::Walk);}else if(state==PlayerState::Walk)SetState(PlayerState::Idle);if(IsKeyPressed(KEY_LEFT_SHIFT)){dashTimer=.12f;dashInvulnerability=.20f;SetState(PlayerState::Dash);AudioSystem::Get().Play(Sfx::Dash);return;}auto beginAttack=[&](AttackType type,float duration,int cs,int ce,int ls,int le,float fd){state=PlayerState::Attack;attackType=type;attackElapsed=0;attackDuration=duration;stateTimer=duration;hasHit=false;energyReleased=false;int start=animator.normalizedAtlas?cs:ls,end=animator.normalizedAtlas?ce:le;animator.Play({start,end,fd,false});};if(IsKeyPressed(KEY_J)){comboStep=(comboWindow>0)?(comboStep+1)%3:0;beginAttack(AttackType::Punch,.30f,8,9,5,9,.15f);AudioSystem::Get().Play(Sfx::Punch);return;}if(IsKeyPressed(KEY_K)){comboStep=3;beginAttack(AttackType::Kick,.36f,10,11,10,14,.16f);AudioSystem::Get().Play(Sfx::Kick);return;}if(IsKeyPressed(KEY_L)&&sp>=20){sp-=20;beginAttack(AttackType::Energy,.52f,12,13,5,9,.13f);AudioSystem::Get().Play(Sfx::EnergyCharge);return;}if(IsKeyPressed(KEY_SPACE)&&rage>=maxRage&&!isRageMode){isRageMode=true;rageDrainAccumulator=0;AudioSystem::Get().Play(Sfx::Rage);return;}spRegenAccumulator+=dt;while(spRegenAccumulator>=.2f&&sp<maxSp){++sp;spRegenAccumulator-=.2f;}}
void Player::AddRage(int amount){if(amount<=0||isRageMode)return;rage=std::min(maxRage,rage+amount);}bool Player::IsBlocking()const{return state==PlayerState::Block;}bool Player::AttackIsActive()const{if(state!=PlayerState::Attack)return false;if(attackType==AttackType::Punch)return attackElapsed>=.09f&&attackElapsed<=.22f;if(attackType==AttackType::Kick)return attackElapsed>=.11f&&attackElapsed<=.28f;if(attackType==AttackType::Energy)return attackElapsed>=.20f&&attackElapsed<=.43f;return false;}int Player::GetAttackDamage()const{int d=10;if(attackType==AttackType::Kick)d=14;if(attackType==AttackType::Energy)d=18;if(comboStep>=2&&attackType==AttackType::Punch)d+=4;if(isRageMode)d=(int)std::round(d*1.35f);return d;}float Player::GetAttackRange()const{if(attackType==AttackType::Kick)return 135.f;if(attackType==AttackType::Energy)return 220.f;return 115.f;}float Player::GetAttackDepthRange()const{return attackType==AttackType::Energy?55.f:42.f;}float Player::GetAttackKnockback()const{if(attackType==AttackType::Kick)return 420.f;if(attackType==AttackType::Energy)return 500.f;return 300.f;}CombatBox Player::GetHurtbox()const{return{position.x-24.f,position.y-112.f,48.f,105.f};}CombatBox Player::GetAttackHitbox()const{if(!AttackIsActive())return{};float d=facing==Facing::Right?1.f:-1.f,w=82.f,h=48.f,forward=54.f,cy=position.y-76.f;if(attackType==AttackType::Kick){w=122;h=58;forward=66;cy=position.y-64;}else if(attackType==AttackType::Energy){w=220;h=76;forward=122;cy=position.y-72;}float cx=position.x+d*forward;return{cx-w*.5f,cy-h*.5f,w,h};}
void Player::TakeDamage(int damage){if(state==PlayerState::Defeat||dashInvulnerability>0)return;if(IsBlocking()){int reduced=std::max(1,(int)std::round(damage*(1.f-blockDamageReduction)));hp=std::max(1,hp-reduced);AddRage(12);velocity.x+=(facing==Facing::Right?-1.f:1.f)*55.f;return;}if(state==PlayerState::Hit&&stateTimer>0)return;hp=std::max(0,hp-damage);AddRage(15);if(hp==0)SetState(PlayerState::Defeat);else{SetState(PlayerState::Hit);dashInvulnerability=.28f;}}
void Player::Draw()const{Vector2 p=position.ToScreen();float ds=DepthScale(position.y),vs=animator.normalizedAtlas?1.10f*ds:.76f*ds;DrawEllipse((int)p.x,(int)p.y,30*ds,8*ds,{0,0,0,145});if(animator.texture.id!=0){Color tint=WHITE;if(state==PlayerState::Hit)tint={255,190,190,255};if(state==PlayerState::Block)tint={175,220,255,255};if(isRageMode)tint={190,220,255,255};animator.Draw(p,vs,facing==Facing::Left,tint);if(IsBlocking()){float pulse=43.f+std::sin((float)GetTime()*12.f)*4.f;DrawCircleLines((int)p.x,(int)(p.y-70*ds),pulse*ds,{80,190,255,160});DrawText("BLOQUEO",(int)p.x-35,(int)p.y-150,12,{120,215,255,230});}if(isRageMode){float pulse=(38.f+std::sin((float)GetTime()*10.f)*6.f)*ds;DrawCircleLines((int)p.x,(int)(p.y-64*ds),pulse,{0,170,255,120});DrawCircleLines((int)p.x,(int)(p.y-64*ds),pulse*.72f,{120,230,255,90});}if(state==PlayerState::Attack&&attackType==AttackType::Energy){float charge=std::clamp(attackElapsed/.20f,0.f,1.f);DrawCircleLines((int)(p.x+(facing==Facing::Right?28:-28)),(int)(p.y-75),12+18*charge,{50,210,255,120});if(energyReleased)DrawCircle((int)(p.x+(facing==Facing::Right?45:-45)),(int)(p.y-76),6,{120,240,255,230});}}else{Color c=BLUE;if(state==PlayerState::Hit)c=RED;else if(state==PlayerState::Attack)c=YELLOW;else if(state==PlayerState::Block)c=Color{80,190,255,255};DrawRectangle((int)(p.x-18*ds),(int)(p.y-68*ds),(int)(36*ds),(int)(68*ds),c);}}
}
